intro:
Searches for the next occurrence of pattern in the underlying view. Equivalent to:

auto [b, e] = ranges::search(ranges::subrange(it, ranges::end(base_)), pattern_);



if (b != ranges::end(base_) and ranges::empty(pattern_))

{

    ++b;

    ++e;

}



return {b, e};

recommendedExamples.code:
#include <cassert>
#include <ranges>
#include <string_view>

int main() {
    constexpr std::string_view keywords{"bitand bitor bool break"};
    std::ranges::split_view kw{keywords, ' '};
    assert(4 == std::ranges::distance(kw.begin(), kw.end()));
}
